import type { Wallet, WalletMetadata, WalletProvider } from "@pact-toolbox/wallet-core";
import { MetaMaskSnapWallet } from "./wallet";

/**
 * MetaMask Snap wallet provider
 */
export class MetaMaskSnapWalletProvider implements WalletProvider {
  readonly id = "metamask-snap";

  readonly metadata: WalletMetadata = {
    id: "metamask-snap",
    name: "MetaMask Snap",
    description: "MetaMask Snap for Kadena blockchain",
    icon: "data:image/svg+xml;base64,",
    type: "browser-extension",
  };

  private snapId?: string;

  constructor(snapId?: string) {
    this.snapId = snapId;
  }

  async isAvailable(): Promise<boolean> {
    return typeof window !== "undefined" && Boolean((window as any).ethereum?.isMetaMask);
  }

  async createWallet(): Promise<Wallet> {
    return new MetaMaskSnapWallet(this.snapId);
  }
}